(x, y, t) => {
  const cx = 240, cy = 120;
  const f1 = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.2)*12;
  const f2 = Math.cos(y*0.016-t*0.25)*14 + Math.sin(x*0.021+t*0.35)*9;
  const f3 = Math.sin((x+y)*0.008+t*0.15)*20;
  const sx = x+f1+f3*0.5, sy = y+f2+f3*0.5;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.5],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.0],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 2.0],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 2.5],
    [60+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*90, 0.11, 2.1, 3.0],
    [420+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+2)*50, 0.085, 1.8, 3.5]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,ph] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w = Math.sin(d*f-t*sp+ph)*Math.exp(-d*0.003);
    aS += w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+ph+1.5)*Math.exp(-d*0.004);
    cS += Math.sin(d*f*1.3-t*sp*0.4+ph*2)*Math.exp(-d*0.002);
  }
  const act=aS/8, inh=iS/8, cor=cS/8;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.8)+Math.sin(sx*0.028-sy*0.038+t*1.1))/2
    +Math.sin((sx+sy)*0.11+t*2.5)*0.2+Math.sin((sx-sy)*0.09-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3-t*1.5)+Math.sin(dist*0.035+ang*4-t*1.2))*0.35;
  const radial=Math.sin(dist*0.08-t*1.8)*0.15*Math.cos(ang*2+t*0.3);
  const micro=(Math.sin(sx*0.22+t*1.5)*Math.sin(sy*0.22-t*1.2)+Math.sin((sx+sy)*0.16+t)*0.4)*0.25;
  const react=Math.tanh((act-inh*0.65+cor*0.35+bg*0.3+spiral+radial)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+micro)*1.4)*0.25;
  const diff=Math.tanh((act*act-inh*inh+cor*0.5)*1.2)*0.15;
  const blend=react*0.6+cell*0.2+diff*0.2, v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[12,45,95],[18,95,120],[25,150,135],[140,185,90],
    [220,190,60],[215,130,65],[185,70,70],[120,35,75],[55,18,58],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(react*Math.PI)*0.15;
  const edge=Math.abs(react)>0.65?1.12:1.0;
  const glow=Math.max(0,react*0.15);
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*20)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*50)|0
  ];
}
